using System.Reflection;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(IPaymentGateway).Assembly;
    private static readonly Assembly InfrastructureAssembly = typeof(HttpPaymentGateway).Assembly;

    private static readonly string[] TechnicalAssemblies =
    [
        "System.Net.Http",
        "System.Net.Primitives",
        "System.IO.FileSystem",
        "System.Data",
        "System.Data.Common",
        "System.Diagnostics.Process",
        "Microsoft.Extensions.*",
        "Microsoft.EntityFrameworkCore*",
    ];

    private static IEnumerable<string> References(Assembly assembly) =>
        assembly.GetReferencedAssemblies().Select(a => a.Name!);

    [Fact]
    public void Domain_depends_on_no_other_layer()
    {
        var offenders = References(DomainAssembly).Where(n =>
            n == ApplicationAssembly.GetName().Name || n == InfrastructureAssembly.GetName().Name);

        Assert.Empty(offenders);
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        Assert.DoesNotContain(InfrastructureAssembly.GetName().Name, References(ApplicationAssembly));
    }

    [Theory]
    [MemberData(nameof(InnerLayers))]
    public void Inner_layers_do_not_reference_technical_assemblies(Assembly layer)
    {
        var offenders = References(layer).Where(IsTechnical);

        Assert.Empty(offenders);
    }

    public static TheoryData<Assembly> InnerLayers() => new() { DomainAssembly, ApplicationAssembly };

    private static bool IsTechnical(string name) =>
        TechnicalAssemblies.Any(p => p.EndsWith('*') ? name.StartsWith(p[..^1]) : name == p);
}
